+import { LINEAR_UNITS, TEMPERATURE_UNITS, type Kind } from "./units.ts";
+
 /** Convert `value` from one unit to another of the same kind. See README.md. */
 export function convert(value: number, from: string, to: string): number {
-  throw new Error("not implemented");
+  const fromKind = unitKind(from);
+  if (!fromKind) {
+    throw new Error(`unknown unit: ${from}`);
+  }
+
+  const toKind = unitKind(to);
+  if (!toKind) {
+    throw new Error(`unknown unit: ${to}`);
+  }
+
+  if (fromKind !== toKind) {
+    throw new Error(`cannot convert ${from} to ${to}`);
+  }
+
+  if (from === to) {
+    return value;
+  }
+
+  if (fromKind === "temperature") {
+    assertAboveAbsoluteZero(value, from);
+    const celsius = toCelsius(value, from);
+    return fromCelsius(celsius, to);
+  }
+
+  const fromUnit = LINEAR_UNITS[from];
+  const toUnit = LINEAR_UNITS[to];
+  return (value * fromUnit.factor) / toUnit.factor;
 }
+
+function unitKind(unit: string): Kind | "temperature" | null {
+  if (unit in LINEAR_UNITS) {
+    return LINEAR_UNITS[unit].kind;
+  }
+
+  if ((TEMPERATURE_UNITS as readonly string[]).includes(unit)) {
+    return "temperature";
+  }
+
+  return null;
+}
+
+function assertAboveAbsoluteZero(value: number, unit: string): void {
+  if ((unit === "C" && value < -273.15) || (unit === "F" && value < -459.67) || (unit === "K" && value < 0)) {
+    throw new RangeError("temperature below absolute zero");
+  }
